import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage } from '@/lib/admin-client';

type Article = { id: string; title_ar: string; slug?: string; status?: string; scheduled_at?: string; updatedAt?: string; tags?: string[] };
type Coupon = { id: string; code: string; title_ar?: string; discount_type: 'percent' | 'amount'; value: number; min_basket?: number; max_discount_cap?: number; usage_limit_total?: number; used_count?: number; active: boolean; expires_at?: string; segments?: string[] };
type Campaign = { id: string; name: string; title: string; body: string; segment: string; status: string; scheduled_at?: string; stats?: { targeted?: number; sent?: number; variants?: Record<string, number> }; variants?: Array<{ id: string; title: string; body: string }> };
type NotificationSegments = { all: number; patients: number; providers: number; by_role: Record<string, number> };

export default function ContentGrowthPage() {
  const [tab, setTab] = useState<'articles' | 'coupons' | 'campaigns'>('articles'); const [articles, setArticles] = useState<Article[]>([]); const [coupons, setCoupons] = useState<Coupon[]>([]); const [campaigns, setCampaigns] = useState<Campaign[]>([]); const [audiences, setAudiences] = useState<NotificationSegments | null>(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [article, setArticle] = useState({ title_ar: '', title_en: '', excerpt_ar: '', body_ar: '', slug: '', tags: '', reason: '', scheduled_at: '' }); const [coupon, setCoupon] = useState({ code: '', title_ar: '', discount_type: 'percent', value: '', min_basket: '', max_discount_cap: '', usage_limit_total: '', expires_at: '', reason: '' }); const [campaign, setCampaign] = useState({ name: '', title: '', body: '', segment: 'patients', scheduled_at: '', route: '', variantBTitle: '', variantBBody: '', confirmed: false });
  const load = useCallback(async () => { setLoading(true); setError(''); try { const [a, c, p, s] = await Promise.all([adminFetch<{ data: Article[] }>('/cms/articles?status=&page=1&limit=100'), adminFetch<Coupon[]>('/coupons'), adminFetch<{ data: Campaign[] }>('/notification-center/campaigns?page=1&limit=100'), adminFetch<NotificationSegments>('/notification-center/segments')]); setArticles(a.data || []); setCoupons(c); setCampaigns(p.data || []); setAudiences(s); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل المحتوى والنمو.')); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function saveArticle(event: React.FormEvent) { event.preventDefault(); if (article.reason.trim().length < 5) { setError('سبب تحرير المحتوى مطلوب.'); return; } setSaving(true); try { const saved: Article = await adminMutation('/cms/articles', 'POST', { ...article, tags: article.tags.split(',').map((tag) => tag.trim()).filter(Boolean), scheduled_at: undefined }); if (article.scheduled_at) await adminMutation(`/cms/articles/${encodeURIComponent(saved.id)}/schedule`, 'POST', { scheduled_at: article.scheduled_at, reason: article.reason }); else await adminMutation(`/cms/articles/${encodeURIComponent(saved.id)}/publish`, 'POST', { reason: article.reason }); setArticle({ title_ar: '', title_en: '', excerpt_ar: '', body_ar: '', slug: '', tags: '', reason: '', scheduled_at: '' }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ المقال.')); } finally { setSaving(false); } }
  async function saveCoupon(event: React.FormEvent) { event.preventDefault(); if (coupon.reason.trim().length < 5) { setError('سبب إنشاء الكوبون مطلوب.'); return; } setSaving(true); try { await adminMutation('/coupons', 'POST', { code: coupon.code, title_ar: coupon.title_ar, discount_type: coupon.discount_type, value: Number(coupon.value), min_basket: Number(coupon.min_basket || 0), max_discount_cap: coupon.max_discount_cap ? Number(coupon.max_discount_cap) : null, usage_limit_total: coupon.usage_limit_total ? Number(coupon.usage_limit_total) : null, expires_at: coupon.expires_at || null, reason: coupon.reason }); setCoupon({ code: '', title_ar: '', discount_type: 'percent', value: '', min_basket: '', max_discount_cap: '', usage_limit_total: '', expires_at: '', reason: '' }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إنشاء الكوبون.')); } finally { setSaving(false); } }
  async function toggleCoupon(item: Coupon) { const reason = window.prompt(`سبب ${item.active ? 'إيقاف' : 'تفعيل'} ${item.code}:`); if (!reason || reason.trim().length < 5) return; setSaving(true); try { await adminMutation(`/coupons/${encodeURIComponent(item.id)}`, 'PATCH', { active: !item.active, reason: reason.trim() }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تغيير حالة الكوبون.')); } finally { setSaving(false); } }
  async function saveCampaign(event: React.FormEvent) { event.preventDefault(); if (!campaign.confirmed) { setError('يجب تأكيد الجمهور قبل إنشاء الحملة.'); return; } setSaving(true); try { await adminMutation('/notification-center/campaigns', 'POST', { name: campaign.name, title: campaign.title, body: campaign.body, segment: campaign.segment, scheduled_at: campaign.scheduled_at || undefined, deep_link: campaign.route ? { route: campaign.route } : undefined, audience_confirmed: true, variants: campaign.variantBTitle && campaign.variantBBody ? [{ id: 'A', title: campaign.title, body: campaign.body }, { id: 'B', title: campaign.variantBTitle, body: campaign.variantBBody }] : [] }); setCampaign({ name: '', title: '', body: '', segment: 'patients', scheduled_at: '', route: '', variantBTitle: '', variantBBody: '', confirmed: false }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إنشاء الحملة.')); } finally { setSaving(false); } }
  async function sendCampaign(item: Campaign) { if (!window.confirm(`سيتم إدراج الإشعارات الحقيقية لجمهور «${item.segment}». إرسال الآن؟`)) return; setSaving(true); try { await adminMutation(`/notification-center/campaigns/${encodeURIComponent(item.id)}/send`, 'POST'); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إرسال الحملة.')); } finally { setSaving(false); } }
  return <><Head><title>المحتوى والنمو | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">المحتوى والنمو</h1><p className="mt-1 text-sm text-slate-500">CMS وكوبونات وحملات Push كلها مرتبطة بمسارات backend وشرائح جمهور محسوبة فعلياً.</p></header><div className="flex flex-wrap gap-2">{(['articles', 'coupons', 'campaigns'] as const).map((item) => <button key={item} onClick={() => setTab(item)} className={`rounded-lg px-4 py-2 text-sm font-bold ${tab === item ? 'bg-teal-700 text-white' : 'border bg-white'}`}>{item === 'articles' ? 'المقالات' : item === 'coupons' ? 'الكوبونات والعروض' : 'حملات Push وA/B'}</button>)}</div>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{loading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ تحميل البيانات…</p> : null}{!loading && tab === 'articles' ? <div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">المقالات الحالية</h2><ul className="mt-4 divide-y">{articles.map((row) => <li key={row.id} className="py-3"><strong>{row.title_ar}</strong><p className="mt-1 text-xs text-slate-500">{row.status} · {row.slug || row.id} · {(row.tags || []).join('، ')}</p></li>)}</ul></article><form onSubmit={saveArticle} className="space-y-3 rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">إنشاء ونشر/جدولة مقال</h2><input required value={article.title_ar} onChange={(e) => setArticle({ ...article, title_ar: e.target.value })} className="w-full rounded-lg border p-2" placeholder="العنوان العربي"/><input value={article.title_en} onChange={(e) => setArticle({ ...article, title_en: e.target.value })} className="w-full rounded-lg border p-2" placeholder="العنوان الإنجليزي"/><input value={article.slug} onChange={(e) => setArticle({ ...article, slug: e.target.value })} dir="ltr" className="w-full rounded-lg border p-2" placeholder="slug"/><input value={article.tags} onChange={(e) => setArticle({ ...article, tags: e.target.value })} className="w-full rounded-lg border p-2" placeholder="وسوم مفصولة بفاصلة"/><textarea value={article.excerpt_ar} onChange={(e) => setArticle({ ...article, excerpt_ar: e.target.value })} className="min-h-16 w-full rounded-lg border p-2" placeholder="ملخص"/><textarea required value={article.body_ar} onChange={(e) => setArticle({ ...article, body_ar: e.target.value })} className="min-h-40 w-full rounded-lg border p-2" placeholder="نص المقال"/><label className="block text-sm">تاريخ النشر (اختياري للتشغيل الفوري)<input type="datetime-local" value={article.scheduled_at} onChange={(e) => setArticle({ ...article, scheduled_at: e.target.value })} className="mt-1 w-full rounded-lg border p-2"/></label><textarea required minLength={5} value={article.reason} onChange={(e) => setArticle({ ...article, reason: e.target.value })} className="min-h-16 w-full rounded-lg border p-2" placeholder="سبب التعديل"/><button disabled={saving} className="rounded bg-teal-700 px-4 py-2 font-bold text-white disabled:opacity-50">حفظ وتدقيق</button></form></div> : null}{!loading && tab === 'coupons' ? <div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الكوبونات الحالية</h2><ul className="mt-4 divide-y">{coupons.map((row) => <li key={row.id} className="flex items-center justify-between gap-3 py-3"><div><strong dir="ltr">{row.code}</strong><p className="mt-1 text-xs text-slate-500">{row.discount_type === 'percent' ? `${row.value}%` : `${row.value} ر.س`} · استخدام {row.used_count ?? 0}/{row.usage_limit_total ?? '∞'}</p></div><button disabled={saving} onClick={() => void toggleCoupon(row)} className="rounded border px-3 py-1 text-xs">{row.active ? 'إيقاف' : 'تفعيل'}</button></li>)}</ul></article><form onSubmit={saveCoupon} className="grid gap-3 rounded-2xl border bg-white p-6 shadow-sm md:grid-cols-2"><h2 className="col-span-full text-xl font-bold">إنشاء عرض</h2><input required value={coupon.code} onChange={(e) => setCoupon({ ...coupon, code: e.target.value.toUpperCase() })} dir="ltr" className="rounded-lg border p-2" placeholder="CODE"/><input value={coupon.title_ar} onChange={(e) => setCoupon({ ...coupon, title_ar: e.target.value })} className="rounded-lg border p-2" placeholder="العنوان"/><select value={coupon.discount_type} onChange={(e) => setCoupon({ ...coupon, discount_type: e.target.value })} className="rounded-lg border p-2"><option value="percent">نسبة</option><option value="amount">مبلغ</option></select><input required value={coupon.value} onChange={(e) => setCoupon({ ...coupon, value: e.target.value })} type="number" min="0.01" className="rounded-lg border p-2" placeholder="القيمة"/><input value={coupon.min_basket} onChange={(e) => setCoupon({ ...coupon, min_basket: e.target.value })} type="number" min="0" className="rounded-lg border p-2" placeholder="حد السلة"/><input value={coupon.max_discount_cap} onChange={(e) => setCoupon({ ...coupon, max_discount_cap: e.target.value })} type="number" min="0" className="rounded-lg border p-2" placeholder="سقف الخصم"/><input value={coupon.usage_limit_total} onChange={(e) => setCoupon({ ...coupon, usage_limit_total: e.target.value })} type="number" min="1" className="rounded-lg border p-2" placeholder="حد الاستخدام الكلي"/><input value={coupon.expires_at} onChange={(e) => setCoupon({ ...coupon, expires_at: e.target.value })} type="datetime-local" className="rounded-lg border p-2"/><textarea required minLength={5} value={coupon.reason} onChange={(e) => setCoupon({ ...coupon, reason: e.target.value })} className="col-span-full min-h-16 rounded-lg border p-2" placeholder="سبب الإنشاء"/><button disabled={saving} className="rounded bg-teal-700 px-4 py-2 font-bold text-white disabled:opacity-50">إنشاء وتدقيق</button></form></div> : null}{!loading && tab === 'campaigns' ? <div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الحملات</h2><p className="mt-1 text-sm text-slate-500">الجمهور الحالي: الكل {audiences?.all ?? 0} · المرضى {audiences?.patients ?? 0} · المزودون {audiences?.providers ?? 0}</p><ul className="mt-4 divide-y">{campaigns.map((row) => <li key={row.id} className="flex items-start justify-between gap-3 py-3"><div><strong>{row.name}</strong><p className="mt-1 text-sm text-slate-600">{row.title}</p><p className="mt-1 text-xs text-slate-500">{row.status} · {row.segment} · مستهدف {row.stats?.targeted ?? '—'} · {row.variants?.length === 2 ? 'A/B مفعل' : 'نسخة واحدة'}</p></div>{['draft', 'scheduled'].includes(row.status) ? <button disabled={saving} onClick={() => void sendCampaign(row)} className="rounded bg-teal-700 px-3 py-1 text-xs text-white">إرسال الآن</button> : null}</li>)}</ul></article><form onSubmit={saveCampaign} className="space-y-3 rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">منشئ حملة Push</h2><input required value={campaign.name} onChange={(e) => setCampaign({ ...campaign, name: e.target.value })} className="w-full rounded-lg border p-2" placeholder="اسم الحملة"/><input required value={campaign.title} onChange={(e) => setCampaign({ ...campaign, title: e.target.value })} className="w-full rounded-lg border p-2" placeholder="عنوان النسخة A"/><textarea required value={campaign.body} onChange={(e) => setCampaign({ ...campaign, body: e.target.value })} className="min-h-20 w-full rounded-lg border p-2" placeholder="نص النسخة A"/><select value={campaign.segment} onChange={(e) => setCampaign({ ...campaign, segment: e.target.value })} className="w-full rounded-lg border p-2"><option value="patients">المرضى</option><option value="providers">المزودون</option><option value="all">كل المستخدمين</option>{Object.keys(audiences?.by_role || {}).map((role) => <option key={role} value={`role:${role}`}>{role}</option>)}</select><input value={campaign.route} onChange={(e) => setCampaign({ ...campaign, route: e.target.value })} dir="ltr" className="w-full rounded-lg border p-2" placeholder="مسار deep link اختياري يبدأ بـ /"/><label className="block text-sm">جدولة اختيارية<input type="datetime-local" value={campaign.scheduled_at} onChange={(e) => setCampaign({ ...campaign, scheduled_at: e.target.value })} className="mt-1 w-full rounded-lg border p-2"/></label><hr/><h3 className="font-bold">اختبار A/B اختياري</h3><input value={campaign.variantBTitle} onChange={(e) => setCampaign({ ...campaign, variantBTitle: e.target.value })} className="w-full rounded-lg border p-2" placeholder="عنوان النسخة B"/><textarea value={campaign.variantBBody} onChange={(e) => setCampaign({ ...campaign, variantBBody: e.target.value })} className="min-h-20 w-full rounded-lg border p-2" placeholder="نص النسخة B"/><label className="flex gap-2 text-sm"><input type="checkbox" checked={campaign.confirmed} onChange={(e) => setCampaign({ ...campaign, confirmed: e.target.checked })}/> أؤكد الجمهور قبل إنشاء الحملة.</label><button disabled={saving} className="rounded bg-teal-700 px-4 py-2 font-bold text-white disabled:opacity-50">إنشاء الحملة</button></form></div> : null}</section></>;
}
